import { summonSanctifier, inspectText, inspectTextDetailed, getRecommendedSanctifierOptions } from '../dist/text-sanctifier.min.js';


// We'll create multiple sanitizers to simulate the options
const strictSanctify = summonSanctifier.strict;
const looseSanctify = summonSanctifier.loose;

const customSanctify = summonSanctifier({
  purgeInvisibleChars: true,
  normalizeNewlines: true,
  collapseNewLines: true,
  collapseSpaces: true,
  trimSpacesAroundNewlines: true,
  nukeControls: true,
  finalTrim: true,
});

const aggressiveSanctifier = summonSanctifier({
  purgeInvisibleChars: true,
  preserveParagraphs: false,
  normalizeNewlines: true,
  collapseNewLines: true,
  collapseSpaces: true,
  nukeControls: true,
  trimSpacesAroundNewlines: true,
  finalTrim: true,
});


function assertEqual(actual, expected, message) {
  if (actual !== expected) {
    console.error(`❌ ${message}\n  Expected: "${expected}"\n  Received: "${actual}"`);
    process.exitCode = 1;
  } else {
    console.log(`✅ ${message}`);
  }
}

console.log('Running text-sanctifier dist tests...');

// 1. Basic invisible character purge
assertEqual(
  customSanctify('Hello\u200BWorld'),
  'HelloWorld',
  '1. Purge zero-width space'
);

// 2. Normalize CRLF line endings
assertEqual(
  customSanctify('Line1\r\nLine2\rLine3'),
  'Line1\nLine2\nLine3',
  '2. Normalize line endings to Unix \\n'
);

// 3. Collapse multiple spaces (using strict)
assertEqual(
  strictSanctify('Hello   World'),
  'Hello World',
  '3. Collapse multiple spaces into one (strict)'
);

// 4. Collapse multiple newlines (loose)
assertEqual(
  looseSanctify('Line1\n\n\nLine2'),
  'Line1\n\nLine2',
  '4. Preserve paragraph breaks (2 newlines) (loose)'
);

// 5. Summoned sanitizer (aggressive)
assertEqual(
  aggressiveSanctifier('A\t\n\n\u0008B'),
  'A\nB',
  '5. Aggressively nuke control chars and collapse newlines'
);

// 6. Trim spaces around newlines
assertEqual(
  customSanctify('Line1   \n   Line2'),
  'Line1\nLine2',
  '6. Trim spaces around newlines'
);

// 7. Preserve tabs even when collapsing spaces
assertEqual(
  strictSanctify('Hello\t\tWorld'),
  'Hello\t\tWorld',
  '7. Preserve tabs even in strict mode'
);

// 8. Purge mixed Unicode junk
assertEqual(
  customSanctify('\u200B\u200C\u200D Hello\u200F\u202DWorld\u202E'),
  'HelloWorld',
  '8. Purge diverse invisible Unicode trash'
);

// 9. Collapse 6+ newlines into paragraph break
assertEqual(
  looseSanctify('A\n\n\n\n\n\nB'),
  'A\n\nB',
  '9. Collapse 6+ newlines into \\n\\n paragraph'
);

// 10. No collapse when paragraph preservation off
assertEqual(
  strictSanctify('X\n\nY'),
  'X\nY',
  '10. Collapse double newline to single (strict)'
);

// 11. Fully purge ghost characters
const ghostInput = 'A\u200B\u200C\u200D\u2060\uFEFF\u200E\u200F\u202A\u202E\u00A0B';
assertEqual(
  customSanctify(ghostInput),
  'AB',
  '11. Ghostproof: Fully purge invisible Unicode'
);







// 12. Keyboard-onlyEmoji: preserve ASCII + emojis, strip non-keyboard extras
const keyboardEmojiSanctifier = summonSanctifier.keyboardOnlyEmoji;

assertEqual(
  keyboardEmojiSanctifier('Hello — World 😊 👽 𝌆 ‼️'),
  'Hello - World 😊 👽  ‼️',
  '12. keyboardOnlyEmoji: normalize dashes and preserve emojis'
);

// 13. Keyboard-onlyEmoji: normalize smart quotes and dashes
assertEqual(
  keyboardEmojiSanctifier(`“Hello”—‘World’`),
  '"Hello"-\'World\'',
  '13. keyboardOnlyEmoji: normalize smart quotes and dashes'
);

// 14. Keyboard-only strict: purge emojis and normalize symbols
const keyboardStrict = summonSanctifier.keyboardOnly;

assertEqual(
  keyboardStrict('Hi 😊 — “there”! 👋'),
  'Hi - "there"!',
  '14. keyboardOnly: emojis removed, symbols normalized, spaces collapsed'
);

// 15. Keyboard-onlyEmoji: normalize full-width ASCII punctuation
assertEqual(
  keyboardEmojiSanctifier('Ｈｅｌｌｏ！Ｗｏｒｌｄ？'),
  'Hello!World?',
  '15. keyboardOnlyEmoji: full-width punctuation normalized'
);








// 16. Bidi isolates and the Arabic letter mark are purged by the dist build
{
  const input = 'A' + [0x061C, 0x2066, 0x2067, 0x2068, 0x2069].map(cp => String.fromCharCode(cp)).join('') + 'B';
  assertEqual(customSanctify(input), 'AB', '16. Purge bidi isolates and ALM');
}

// 17. The dist build keeps the public property names (Closure ADVANCED renames anything not in externs)
{
  const report = inspectText('A' + String.fromCharCode(0x2066) + 'B');
  assertEqual(report.hasControlChars, true, '17. inspectText.hasControlChars survives minification');
  assertEqual(getRecommendedSanctifierOptions(report).nukeControls, true, '17. getRecommendedSanctifierOptions survives minification');

  const detailed = inspectTextDetailed(String.fromCharCode(0xFEFF) + 'x' + String.fromCharCode(0x2067), { maxFindings: 1 });
  const f = detailed.findings[0];
  assertEqual(
    JSON.stringify([f.offset, f.line, f.column, f.codePoint, f.category, f.atStart]),
    JSON.stringify([0, 1, 1, 0xFEFF, 'bom', true]),
    '17. inspectTextDetailed finding fields survive minification'
  );
  assertEqual(
    JSON.stringify([detailed.counts.bom, detailed.counts.bidi_control, detailed.total, detailed.truncated]),
    JSON.stringify([1, 1, 2, true]),
    '17. inspectTextDetailed counts/total/truncated and maxFindings survive minification'
  );
}

// 18. Astral trash (tag characters) is located and purged by the dist build, and the new counts survive
{
  const tags = [0xE0048, 0xE0069].map(cp => String.fromCodePoint(cp)).join('');
  const detailed = inspectTextDetailed('a' + tags + String.fromCharCode(0x3164));
  assertEqual(
    JSON.stringify(detailed.findings.map(f => [f.offset, f.column, f.codePoint, f.category])),
    JSON.stringify([[1, 2, 0xE0048, 'tag'], [3, 4, 0xE0069, 'tag'], [5, 6, 0x3164, 'hangul_filler']]),
    '18. astral findings survive minification'
  );
  assertEqual(
    JSON.stringify([detailed.counts.tag, detailed.counts.hangul_filler, detailed.counts.variation_selector, detailed.counts.invisible_format]),
    JSON.stringify([2, 1, 0, 0]),
    '18. new count fields survive minification'
  );
  assertEqual(customSanctify('A' + tags + 'B'), 'AB', '18. tag characters purged by the dist build');
}


console.log('All dist tests finished.');
